def gushti_cdi():

    n = int(input())

    arr = list(map(int, input().split()))

    points = 0

    for i in range(n):

        if arr[i] == 0 and i != 0:

            idx = arr.index(max(arr[:i]))

            points += arr[idx]

            arr[idx] = 0

    return points

